CREATE TABLE cmdb_ire_identity_rules (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, class VARCHAR(30) NOT NULL, rule_version BIGINT UNSIGNED NOT NULL, state ENUM('ACTIVE','RETIRED') NOT NULL, definition JSON NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), published_at DATETIME(6) NULL, active_class VARCHAR(30) GENERATED ALWAYS AS (IF(state='ACTIVE',class,NULL)) STORED, UNIQUE KEY cmdb_ire_rule_version(tenant_id,class,rule_version), UNIQUE KEY cmdb_ire_rule_active(tenant_id,active_class), KEY cmdb_ire_rule_class(tenant_id,class,state), CONSTRAINT cmdb_ire_rule_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT cmdb_ire_rule_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
